import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"আবাসন নিশ্চয়তা আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/45-住房保障法.md","filePath":"bn/45-住房保障法.md","lastUpdated":1789183869000}'),i={name:"bn/45-住房保障法.md"};function o(e,t,n,h,s,_){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="আবাসন-নিশ্চয়তা-আইন" tabindex="-1">আবাসন নিশ্চয়তা আইন <a class="header-anchor" href="#আবাসন-নিশ্চয়তা-আইন" aria-label="Permalink to &quot;আবাসন নিশ্চয়তা আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>45</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>আবাসন অধিকার, নিশ্চয়তা আবাসন, স্থান বিধি শাসন, বাসযোগ্য পরিবেশ, জুয়া বিরোধী</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《আবাসন নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার পাঁচটি সহায়ক আইনের একটি, এবং এর উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ভেতরে সমস্ত জীবের আবাসন অধিকার নিশ্চিত করা, ন্যায়বিচারপূর্ণ, টেকসই আবাসন নিশ্চয়তা ব্যবস্থা স্থাপন করা, স্থান বিধি শাসন প্রযুক্তি ব্যবহার করে সকল প্রজাতিকে উপযুক্ত আবাসন স্থান প্রদান করা, এবং আবাসন ক্ষেত্রে জুয়া এবং লুঠের প্রতিরোধ করা।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>আবাসন নিশ্চয়তা নীতি</td><td>প্রতিটি জীব উপযুক্ত আবাসন স্থান পাওয়ার অধিকার রাখে, রাষ্ট্র এবং সভ্যতার মৌলিক আবাসন চাহিদা নিশ্চিত করার বাধ্যতা রয়েছে</td></tr><tr><td>জনকল্যাণ অগ্রাধিকার নীতি</td><td>আবাসন প্রথমে জীবনের প্রয়োজনীয় দ্রব্য, জুয়া পণ্য নয়, নিশ্চয়তা আবাসনের জনকল্যাণ বৈশিষ্ট্য রয়েছে</td></tr><tr><td>স্থান দক্ষতা নীতি</td><td>স্থান বিধি শাসন প্রযুক্তি ব্যবহার করে স্থান ব্যবহারের দক্ষতা বাড়ানো, বাসযোগ্য স্থান প্রসারিত করা</td></tr><tr><td>বিদেশী প্রজাতির অভিযোজন নীতি</td><td>বিভিন্ন প্রজাতির শারীরিক বৈশিষ্ট্য এবং জীবনযাত্রার অভ্যাস অনুযায়ী অভিযোজিত আবাসন স্থান প্রদান করা</td></tr><tr><td>বাসযোগ্য পরিবেশ নীতি</td><td>আবাসন স্থানে ভালো পরিবেশগত পরিবেশ, মৌলিক অবকাঠামো এবং পাবলিক সেবা থাকা উচিত</td></tr><tr><td>জুয়া বিরোধী নীতি</td><td>আবাসনকে লক্ষ্য করে জুয়া করা নিষিদ্ধ, আবাসনকে সম্পদ লুঠের হাতিয়ার হওয়া থেকে বাধা দেওয়া</td></tr></tbody></table><h2 id="_2-আবাসন-অধিকারের-আইনি-নিশ্চয়তা" tabindex="-1">2. আবাসন অধিকারের আইনি নিশ্চয়তা <a class="header-anchor" href="#_2-আবাসন-অধিকারের-আইনি-নিশ্চয়তা" aria-label="Permalink to &quot;2. আবাসন অধিকারের আইনি নিশ্চয়তা&quot;">​</a></h2><p>এই আইন স্পষ্টভাবে নির্ধারণ করে যে, আবাসন অধিকার হল সিম্বায়োসিস সংবিধান দ্বারা প্রতিটি জীবকে প্রদত্ত মৌলিক অধিকার, এবং এর মধ্যে নির্দিষ্টভাবে অন্তর্ভুক্ত:</p><ol><li><strong>মৌলিক আবাসন অধিকার</strong>: প্রতিটি জীব সর্বনিম্ন মানদণ্ডের নিচে না এমন আবাসন স্থান পাওয়ার অধিকার রাখে, সর্বনিম্ন মানদণ্ড প্রজাতির আকার এবং জীবনযাত্রার চাহিদা অনুযায়ী নির্ধারিত হয়।</li><li><strong>আবাসন নিশ্চয়তা আবেদন অধিকার</strong>: যোগ্য জীব নিশ্চয়তা আবাসনের জন্য আবেদন করার অধিকার রাখে, আবেদনের শর্ত এবং বণ্টনের মানদণ্ড খোলা ও স্বচথ।</li><li><strong>আবাসন নিরাপত্তা অধিকার</strong>: আবাসন স্থান নিরাপত্তা মানদণ্ড পূরণ করতে হবে, বিপজ্জনক বাড়ি এবং বাসযোগ্য নয় এমন স্থান ভাড়া দেওয়া বা বণ্টন করা যাবে না।</li><li><strong>আবাসন স্থিতিশীলতা অধিকার</strong>: নিশ্চয়তা আবাসনের বাসিন্দা যোগ্যতার শর্ত পূরণ করার ক্ষেত্রে স্থিতিশীল আবাসন অধিকার উপভোগ করে, এবং অবাধে নির্বাসিত করা যাবে না।</li><li><strong>আবাসন পরিবেশ অধিকার</strong>: বাসিন্দা পরিষ্কার বায়ু, জলের উৎস এবং ভালো আশেপাশের পরিবেশ পাওয়ার অধিকার রাখে, এবং পরিবেশ দূষণের বিরুদ্ধে অভিযোগ করার অধিকার রাখে।</li><li><strong>আবাসন সংস্কার অধিকার</strong>: বাসিন্দা ভবনের নিরাপত্তা এবং অন্যদের অধিকারকে প্রভাবিত না করার শর্তে, আবাসন স্থানে যুক্তিসঙ্গত সংস্কার করার অধিকার রাখে।</li></ol><h2 id="_3-আবাসন-নিশ্চয়তা-ব্যবস্থা" tabindex="-1">3. আবাসন নিশ্চয়তা ব্যবস্থা <a class="header-anchor" href="#_3-আবাসন-নিশ্চয়তা-ব্যবস্থা" aria-label="Permalink to &quot;3. আবাসন নিশ্চয়তা ব্যবস্থা&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতার আবাসন নিশ্চয়তা ব্যবস্থা তিন ধরনের আবাসনে বিভক্ত, এবং বিভিন্ন চাহিদার স্তরকে কভার করে:</p><table tabindex="0"><thead><tr><th>ধরন</th><th>নাম</th><th>নিশ্চয়তা বস্তু</th><th>বণ্টন পদ্ধতি</th><th>ভাড়া/দাম</th></tr></thead><tbody><tr><td>প্রথম ধরন</td><td>পাবলিক ভাড়া আবাসন</td><td>কম আয় গোষ্ঠী, প্রাথমিক সাধক, নতুন অভিবাসী</td><td>আবেদন পরীক্ষা পদ্ধতি, অপেক্ষা বণ্টন</td><td>প্রতীকী কম ভাড়া</td></tr><tr><td>দ্বিতীয় ধরন</td><td>যৌথ মালিকানা আবাসন</td><td>মাঝারি আয় গোষ্ঠী, মাঝারি স্তরের সাধক</td><td>আবেদন পরীক্ষা পদ্ধতি, লটারি বণ্টন</td><td>বাজার দামের নিচে, ব্যক্তি এবং রাষ্ট্র যৌথ মালিকানা</td></tr><tr><td>তৃতীয় ধরন</td><td>পণ্য আবাসন</td><td>উচ্চ আয় গোষ্ঠী, উচ্চস্তরের সাধক</td><td>বাজার লেনদেন</td><td>বাজার দাম, নিয়ন্ত্রণের বাধ্যতা</td></tr></tbody></table><p>এছাড়াও, স্থান ভাঁজ প্রযুক্তি ব্যবহার করে &quot;স্থান ভাঁজ আবাসন অঞ্চল&quot; নির্মাণ করা হয়: সীমিত ভৌত স্থানের ভেতরে স্থান ভাঁজ প্রযুক্তির মাধ্যমে আবাসন এলাকা প্রসারিত করা, উচ্চ ঘনত্বের অঞ্চলে আরও আবাসন স্থান প্রদান করা। স্থান ভাঁজ আবাসন অঞ্চল অবশ্যই নিরাপত্তা মূল্যায়নের মধ্য দিয়ে যেতে হবে, এবং স্থানের স্থিতিশীলতা নিশ্চিত করতে হবে।</p><h2 id="_4-বিদেশী-প্রজাতির-আবাসন-অভিযোজন" tabindex="-1">4. বিদেশী প্রজাতির আবাসন অভিযোজন <a class="header-anchor" href="#_4-বিদেশী-প্রজাতির-আবাসন-অভিযোজন" aria-label="Permalink to &quot;4. বিদেশী প্রজাতির আবাসন অভিযোজন&quot;">​</a></h2><p>হেঙ্গুয়ানঝৌর ভেতরে বিভিন্ন প্রজাতির বিশেষ আবাসন চাহিদার জন্য, এই আইন বিদেশী প্রজাতির আবাসন অভিযোজন ব্যবস্থা স্থাপন করে:</p><ul><li><strong>জলজ প্রজাতি</strong>: পানির নিচে আবাসন স্থান বা জল-স্থল উভচর আবাসন প্রদান করা, জল চক্র এবং পানির মান রক্ষণাবেক্ষণ ব্যবস্থা সজ্জিত করা।</li><li><strong>উড়ন্ত প্রজাতি</strong>: উচ্চতায় আবাসন স্থান বা উড্ডয়ন অবতরণ প্ল্যাটফর্ম সহ আবাসন প্রদান করা, আকাশ যানবাহন পরিচালনা সজ্জিত করা।</li><li><strong>শক্তি জীব</strong>: শক্তির ঘনত্ব উপযুক্ত আবাসন স্থান প্রদান করা, শক্তি স্থিতিশীল যন্ত্র সজ্জিত করা।</li><li><strong>বিশাল প্রজাতি</strong>: বড় মাপের আবাসন স্থান প্রদান করা, ভবনের কাঠামো বিশেষভাবে শক্তিশালী করা।</li><li><strong>ক্ষুদ্র প্রজাতি</strong>: ক্ষুদ্র আবাসন অঞ্চল প্রদান করা, স্কেলিং চ্যানেল এবং বিশেষ সুবিধা সজ্জিত করা।</li></ul><p>বিদেশী প্রজাতির আবাসন অভিযোজন মানদণ্ড আবাসন অধিদপ্তর এবং প্রতিটি প্রজাতির প্রতিনিধি সহযোগিতায় প্রণয়ন করে, এবং নিয়মিত আপডেট করে।</p><h2 id="_5-আবাসন-নির্মাণ-এবং-ব্যবস্থাপনা" tabindex="-1">5. আবাসন নির্মাণ এবং ব্যবস্থাপনা <a class="header-anchor" href="#_5-আবাসন-নির্মাণ-এবং-ব্যবস্থাপনা" aria-label="Permalink to &quot;5. আবাসন নির্মাণ এবং ব্যবস্থাপনা&quot;">​</a></h2><ul><li><strong>আবাসন নির্মাণ পরিকল্পনা</strong>: রাষ্ট্র জনসংখ্যা বৃদ্ধি এবং অভিবাসনের পরিস্থিতি অনুযায়ী আবাসন নির্মাণ পরিকল্পনা প্রণয়ন করে, এবং আবাসনের সরবরাহ এবং চাহিদার ভারসাম্য নিশ্চিত করে।</li><li><strong>নির্মাণ মানদণ্ড</strong>: নিশ্চয়তা আবাসনের নির্মাণ অবশ্যই নিরাপত্তা, পরিবেশগত, বাসযোগ্য মানদণ্ড পূরণ করতে হবে, এবং নির্মাণের মান কমানো নিষিদ্ধ।</li><li><strong>সম্পত্তি ব্যবস্থাপনা</strong>: আবাসন অঞ্চলে স্বায়ত্তশাসন ব্যবস্থাপনা এবং পেশাদার সম্পত্তি ব্যবস্থাপনা একত্রিত মডেল চালু করা, বাসিন্দা সম্পত্তি ব্যবস্থাপনার সিদ্ধান্তে অংশ নেওয়ার অধিকার রাখে।</li><li><strong>আবাসন মেরামত</strong>: নিশ্চয়তা আবাসনের মেরামত আবাসন ব্যবস্থাপনা প্রতিষ্ঠানের দায়িত্ব, এবং মেরামতের তহবিল পাবলিক সঞ্চয় থেকে বহন করা হয়।</li><li><strong>প্রস্থান ব্যবস্থা</strong>: নিশ্চয়তা আবাসনের বাসিন্দার আয় বা সাধনার স্তর নিশ্চয়তা মানদণ্ড অতিক্রম করলে, নিশ্চয়তা আবাসন থেকে প্রস্থান করা বা পণ্য আবাসনে রূপান্তর করা উচিত, এবং প্রস্থানে যুক্তিসঙ্গত অতিবাহিতকালীন সময় দেওয়া হয়।</li></ul><h2 id="_6-জুয়া-বিরোধী-এবং-তদারকি" tabindex="-1">6. জুয়া বিরোধী এবং তদারকি <a class="header-anchor" href="#_6-জুয়া-বিরোধী-এবং-তদারকি" aria-label="Permalink to &quot;6. জুয়া বিরোধী এবং তদারকি&quot;">​</a></h2><p>আবাসন ক্ষেত্রে জুয়া এবং লুঠ প্রতিরোধের জন্য, এই আইন নিম্নলিখিত তদারকি ব্যবস্থা স্থাপন করে:</p><ol><li>ব্যক্তিগত পণ্য আবাসন ধারণ করার সংখ্যা সীমিত করা, সীমা অতিক্রম করলে ক্রমবর্ধমান আবাসন কর আদায় করা।</li><li>নিশ্চয়তা আবাসনের সাবলিজ এবং পুনর্বিক্রয় নিষিদ্ধ, লঙ্ঘনকারীর নিশ্চয়তা যোগ্যতা বাতিল এবং আবাসন ফেরত আদায়।</li><li>আবাসন লেনদেনের তথ্য খোলা ব্যবস্থা স্থাপন করা, অন্ধকার বক্স অপারেশন এবং দাম হেরফের প্রতিরোধ করা।</li><li>রিয়েল এস্টেট ডেভেলপারদের যোগ্যতা ব্যবস্থাপনা এবং তহবিল তদারকি চালু করা, অসম্পূর্ণ নির্মাণ এবং প্রতারণা প্রতিরোধ করা।</li><li>আবাসন অভিযোগ এবং বিবাদ সমাধান ব্যবস্থা স্থাপন করা, বাসিন্দার বৈধ অধিকার নিশ্চিত করা।</li></ol><h2 id="_7-আইনি-দায়বদ্ধতা" tabindex="-1">7. আইনি দায়বদ্ধতা <a class="header-anchor" href="#_7-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;7. আইনি দায়বদ্ধতা&quot;">​</a></h2><p>এই আইনের বিধান লঙ্ঘন করা কার্যক্রম, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ul><li>বিধি বিরোধীভাবে নিশ্চয়তা আবাসন বণ্টন করলে, সংশোধন করার নির্দেশ এবং দায়ী ব্যক্তিকে শাস্তি।</li><li>নিশ্চয়তা আবাসন সাবলিজ, পুনর্বিক্রয় করলে, নিশ্চয়তা যোগ্যতা বাতিল, আবাসন ফেরত আদায় এবং জরিমানা।</li><li>ডেভেলপার নির্মাণের মান কমালে, পুনর্নির্মাণ করার নির্দেশ এবং জরিমানা, গুরুতর অপরাধের ক্ষেত্রে যোগ্যতা বাতিল।</li><li>আবাসন জুয়া করলে, উচ্চ জুয়া কর আদায় এবং জরিমানা।</li><li>বিপজ্জনক বাড়ি ভাড়া দিয়ে বাসিন্দার ক্ষতি সাধন করলে, ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ, গুরুতর অপরাধের ক্ষেত্রে ফৌজদারি দায়বদ্ধতা আরোপ।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《আবাসন নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার &quot;প্রত্যেকের পথ&quot; দর্শনের আবাসন ক্ষেত্রের বাস্তবায়ন। এটি শ্রেণীবিন্যাস আবাসন নিশ্চয়তা ব্যবস্থা স্থাপন করা, স্থান বিধি শাসন প্রযুক্তি ব্যবহার করে আবাসন স্থান প্রসারিত করা, বিদেশী প্রজাতির আবাসন চাহিদার অভিযোজন, আবাসন জুয়া মুছে ফেলার মাধ্যমে, নিশ্চিত করে যে প্রতিটি জীব একটি নিরাপদ, উপযুক্ত, স্থিতিশীল বাড়ির মালিক হতে পারে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য আবাসন নিশ্চয়তা প্রদান করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>39-住房与环境保障 (আবাসন এবং পরিবেশ নিশ্চয়তা)</li><li>13-空间法理调度体系详解 (স্থান বিধি শাসন প্রণালী ব্যবস্থার বিস্তারিত ব্যাখ্যা)</li><li>46-环境保护法 (পরিবেশ সংরক্ষণ আইন)</li></ul>',29)])])}const c=a(i,[["render",o]]);export{u as __pageData,c as default};
